    /**
     * Values shared by the host, the browser bundle, and the tests.
     *
     * Everything in this file is data: option ids, weights, and limits. User
     * facing labels live in `src/client/i18n/*.js` so the same record can be
     * rendered in either language.
     */

    /** Sidebar entry id and main-panel key; both must stay equal. */
    const PANEL_ID = 'fde-workbench';

    /** Locale namespace owned by the plugin. */
    const LOCALE_NS = 'fdeWorkbench';

    /** Delivery stages, from discovery to continuous improvement. */
    const STAGE_COUNT = 8;

    /** Project delivery states. */
    const PROJECT_STATUSES = ['active', 'paused', 'completed', 'stopped'];

    /** Task lifecycle. */
    const TASK_STATUSES = ['todo', 'in_progress', 'blocked', 'done', 'cancelled'];

    /** Task priority. */
    const TASK_PRIORITIES = ['low', 'medium', 'high', 'urgent'];

    /** Source uploads. */
    const MAX_SOURCE_BYTES = 25 * 1024 * 1024;

    /** Finance domains an opportunity can belong to. */
    const DOMAINS = ['reporting', 'ap', 'ar', 'expense', 'close', 'tax', 'audit', 'fpa', 'treasury', 'shared', 'other'];

    /** The AI action an opportunity asks for. */
    const TASK_TYPES = ['extract', 'validate', 'summarize', 'generate', 'classify', 'analyze', 'qa', 'orchestrate'];

    /** Workflow state of an opportunity, independent of its fit verdict. */
    const OPP_STATUSES = ['candidate', 'validating', 'pilot', 'adopted', 'parked', 'rejected'];

    /** Compliance sensitivity; high budgets the verdict at "validate". */
    const COMPLIANCE_LEVELS = ['low', 'medium', 'high'];

    /** Evidence kinds kept per stage. */
    const ARTIFACT_KINDS = ['doc', 'code', 'report', 'record', 'data'];

    /** Blocker severity. */
    const SEVERITIES = ['high', 'medium', 'low'];

    /** Research lifecycle. */
    const RESEARCH_STATUSES = ['open', 'researching', 'finding', 'closed'];

    /** Delivery document lifecycle. */
    const DOC_STATUSES = ['draft', 'review', 'approved', 'archived'];

    /** Built-in document templates. */
    const DOC_TEMPLATES = ['proposal', 'research', 'delivery', 'acceptance', 'retro'];

    /** Feasibility dimensions and weights; they sum to 100. */
    const DIMENSIONS = [
      { key: 'data', weight: 25 },
      { key: 'rules', weight: 25 },
      { key: 'review', weight: 20 },
      { key: 'value', weight: 20 },
      { key: 'adoption', weight: 10 },
    ];

    /** Verdict thresholds, inclusive lower bounds. */
    const SCORE_THRESHOLDS = { pilot: 75, validate: 55 };

    /**
     * Deterministic AI-fit scoring.
     *
     * The model may propose ratings, but the number the workbench shows is always
     * recomputed here: weights are fixed, high compliance caps the verdict, and a
     * weak reviewability score blocks a pilot. Notes are stable codes so the
     * browser can render them in either language.
     */

    /** Clamp one rating to 1–5, defaulting to 3. */
    function clampRating(value) {
      const number = typeof value === 'number' ? value : Number(value);
      if (!Number.isFinite(number)) return 3
      return Math.min(5, Math.max(1, Math.round(number)))
    }

    /** Normalize a ratings object into the five known dimensions. */
    function normalizeRatings(raw) {
      const source = raw !== null && typeof raw === 'object' ? raw : {};
      const ratings = {};
      for (const dimension of DIMENSIONS) ratings[dimension.key] = clampRating(source[dimension.key]);
      return ratings
    }

    /**
     * Score one opportunity.
     * @param {object} ratings - five 1–5 values.
     * @param {string} compliance - `low`, `medium`, or `high`.
     * @returns {object} score, verdict, weakest dimension, ratings, and reason codes.
     */
    function scoreOpportunity(ratings, compliance) {
      const values = normalizeRatings(ratings);
      let weighted = 0;
      let weakest = DIMENSIONS[0].key;
      let weakestValue = Number.POSITIVE_INFINITY;
      for (const dimension of DIMENSIONS) {
        const value = values[dimension.key];
        weighted += (value / 5) * dimension.weight;
        if (value < weakestValue) {
          weakestValue = value;
          weakest = dimension.key;
        }
      }
      const score = Math.round(weighted);
      let verdict = score >= SCORE_THRESHOLDS.pilot ? 'pilot' : score >= SCORE_THRESHOLDS.validate ? 'validate' : 'hold';
      const notes = [];
      if (compliance === 'high') {
        notes.push('compliance-gate');
        if (verdict === 'pilot') {
          verdict = 'validate';
          notes.push('compliance-cap');
        }
        if (values.review <= 2) {
          verdict = 'hold';
          notes.push('review-gate');
        }
      } else if (values.review <= 2) {
        notes.push('review-weak');
      }
      for (const key of ['data', 'rules', 'adoption']) {
        if (values[key] <= 2) notes.push(`weak-${key}`);
      }
      return { score, verdict, weakest, ratings: values, notes }
    }

